schema_ddl:
CREATE TABLE spedizioni (
    codice_spedizione INT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    destinazione TEXT NOT NULL,
    peso_netto TEXT NOT NULL,
    data_partenza DATE NOT NULL,
    CONSTRAINT check_peso_numerico CHECK (peso_netto ~ '^[0-9]+(\.[0-9]+)?$')
);

CREATE TABLE colli (
    id INT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    spedizione_id INT NOT NULL REFERENCES spedizioni(codice_spedizione),
    descrizione TEXT NOT NULL,
    volume_occupato NUMERIC(10, 2) CHECK (volume_occupato BETWEEN 0.01 AND 1000.00)
);
